@Component("merchant-handler")
@ProcessingGroup("merchant-processing-group")
public class MerchantEventHandler {
	
	// core constructor
	MerchantEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateMerchantEvent
     */
    @EventHandler
    public void handle( CreateMerchantEvent event) {
        entityManager.persist(new Merchant(event.getMerchantId(), event.getName(), event.getMcc(), event.getUrl(), event.getCountry(), event.getSettlementCurrency(), event.getTerminals(), event.getPaymentContracts(), event.getPayouts(), event.getSettlements(), event.getDisputes(), event.getInvoices()));
    }

    /*
     * @param	event UpdateMerchantEvent
     */
    @EventHandler
    public Merchant handle( UpdateMerchantEvent event) {
    	entityManager.merge(new Merchant(event.getMerchantId(), event.getName(), event.getMcc(), event.getUrl(), event.getCountry(), event.getSettlementCurrency(), event.getTerminals(), event.getPaymentContracts(), event.getPayouts(), event.getSettlements(), event.getDisputes(), event.getInvoices()));
    }
    
    /*
     * @param	event DeleteMerchantEvent
     */
    @EventHandler
    public void on( DeleteMerchantEvent event) {
    	Merchant entity = new Merchant();
   
    	// ------------------------------------------
    	// apply the MerchantId
    	// ------------------------------------------
    	entity.setMerchantId( event.getMerchantId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final MerchantRepository merchantEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(MerchantEventHandler.class.getName());

}
